import{_ as r,o as s,c as a,ah as l}from"./chunks/framework.C5RNlfrV.js";const c="/projects/AiNex/en/raspberry-pi5-version/assets/image3.IlEuNIjF.png",d="/projects/AiNex/en/raspberry-pi5-version/assets/image2.wfrGb1pU.png",p="/projects/AiNex/en/raspberry-pi5-version/assets/image3.CAJgWEuh.png",h="/projects/AiNex/en/raspberry-pi5-version/assets/image4.D7BfDc1J.png",g="/projects/AiNex/en/raspberry-pi5-version/assets/image5.Cs82DZw5.png",m="/projects/AiNex/en/raspberry-pi5-version/assets/image6.fbNJ5QGC.png",u="/projects/AiNex/en/raspberry-pi5-version/assets/image4.nV6F_Z9P.png",y="/projects/AiNex/en/raspberry-pi5-version/assets/image3.DzN5UIVX.png",b="/projects/AiNex/en/raspberry-pi5-version/assets/image5.CpyIqxeY.png",x="/projects/AiNex/en/raspberry-pi5-version/assets/image6.KcwnbLSN.png",f="/projects/AiNex/en/raspberry-pi5-version/assets/image7.B03ICvtV.png",w="/projects/AiNex/en/raspberry-pi5-version/assets/image2.cWp6vkSA.png",A="/projects/AiNex/en/raspberry-pi5-version/assets/image3.-8S4iOKp.png",v="/projects/AiNex/en/raspberry-pi5-version/assets/image4.GuaxtMrx.png",k="/projects/AiNex/en/raspberry-pi5-version/assets/image5.CmIaNbFm.png",_="/projects/AiNex/en/raspberry-pi5-version/assets/image6.BkykNEuh.png",C="/projects/AiNex/en/raspberry-pi5-version/assets/image7.BPuEMlp_.png",o="/projects/AiNex/en/raspberry-pi5-version/assets/image2.Bjj5xpzc.jpeg",j="/projects/AiNex/en/raspberry-pi5-version/assets/image3.CX69fSZA.png",i="/projects/AiNex/en/raspberry-pi5-version/assets/image4.DlHAt8zd.png",N="/projects/AiNex/en/raspberry-pi5-version/assets/image5.CNf86A3G.png",I="data:image/png;base64,",R="data:image/png;base64,",n="/projects/AiNex/en/raspberry-pi5-version/assets/image8.DRhuHO4u.jpeg",S="/projects/AiNex/en/raspberry-pi5-version/assets/image10.BX7UtfUl.jpeg",q="/projects/AiNex/en/raspberry-pi5-version/assets/image11.Bdk02o3Y.png",P="/projects/AiNex/en/raspberry-pi5-version/assets/image12.DKXpikma.png",z="/projects/AiNex/en/raspberry-pi5-version/assets/image13.D9lPcqDq.png",T="/projects/AiNex/en/raspberry-pi5-version/assets/image14.3OmY5oLV.png",E="/projects/AiNex/en/raspberry-pi5-version/assets/image15.CfntYIeI.png",O="/projects/AiNex/en/raspberry-pi5-version/assets/image2.rSpjHnks.jpeg",F="/projects/AiNex/en/raspberry-pi5-version/assets/image3.0KnNXJQb.jpeg",D="/projects/AiNex/en/raspberry-pi5-version/assets/image4.-W7HyCXU.png",V="/projects/AiNex/en/raspberry-pi5-version/assets/image5.C889mOOr.png",B="/projects/AiNex/en/raspberry-pi5-version/assets/image6.BCRfX0-U.png",W="/projects/AiNex/en/raspberry-pi5-version/assets/image7.BXDFHJD1.png",M="/projects/AiNex/en/raspberry-pi5-version/assets/image8.kLFpmgCV.png",U="/projects/AiNex/en/raspberry-pi5-version/assets/image9.CLwy5ycZ.png",H="/projects/AiNex/en/raspberry-pi5-version/assets/image10.BzSoQYb1.png",L="/projects/AiNex/en/raspberry-pi5-version/assets/image11.DwCodtmU.png",t="data:image/png;base64,",Z="/projects/AiNex/en/raspberry-pi5-version/assets/image13.Mr1JT8wN.jpeg",X="/projects/AiNex/en/raspberry-pi5-version/assets/image14.CF0uEY5c.png",J="/projects/AiNex/en/raspberry-pi5-version/assets/image15.BZrVYutV.png",G="/projects/AiNex/en/raspberry-pi5-version/assets/image16.DkAwsdFf.png",K="/projects/AiNex/en/raspberry-pi5-version/assets/image17.CSwCWxZ3.png",Y="/projects/AiNex/en/raspberry-pi5-version/assets/image18.DFKeBKnb.png",Q="/projects/AiNex/en/raspberry-pi5-version/assets/image19.C0upG37i.png",$="/projects/AiNex/en/raspberry-pi5-version/assets/image20.BdASKLC3.jpeg",tt="/projects/AiNex/en/raspberry-pi5-version/assets/image21.DEtAPIlO.jpeg",et="/projects/AiNex/en/raspberry-pi5-version/assets/image22.-Z22Dl7P.jpeg",ot="/projects/AiNex/en/raspberry-pi5-version/assets/image23.BX-S5F0L.jpeg",it="/projects/AiNex/en/raspberry-pi5-version/assets/image24.CFV8dBiK.png",nt="/projects/AiNex/en/raspberry-pi5-version/assets/image25.DtLemHio.png",rt="/projects/AiNex/en/raspberry-pi5-version/assets/image26.FmKJZAFQ.png",st="/projects/AiNex/en/raspberry-pi5-version/assets/image27.CK3jAMU5.png",at="/projects/AiNex/en/raspberry-pi5-version/assets/image28.ZhRHqnDT.png",lt="/projects/AiNex/en/raspberry-pi5-version/assets/image29.DnWZjuxB.jpeg",ct="/projects/AiNex/en/raspberry-pi5-version/assets/image30.BFMZXDc3.jpeg",dt="/projects/AiNex/en/raspberry-pi5-version/assets/image31.zYkfg-U9.jpeg",pt="/projects/AiNex/en/raspberry-pi5-version/assets/image32.DmzRetUH.jpeg",ht="/projects/AiNex/en/raspberry-pi5-version/assets/image33.BWEOtuMB.png",gt="/projects/AiNex/en/raspberry-pi5-version/assets/image34.mXg_o21L.png",mt="/projects/AiNex/en/raspberry-pi5-version/assets/image35.B8LZ0FTm.png",ut="/projects/AiNex/en/raspberry-pi5-version/assets/image36.C4LzaItr.png",yt="/projects/AiNex/en/raspberry-pi5-version/assets/image37.Dy97quQn.png",bt="/projects/AiNex/en/raspberry-pi5-version/assets/image38.Czojj7o0.jpeg",xt="/projects/AiNex/en/raspberry-pi5-version/assets/image39.G1KW3uXH.png",ft="/projects/AiNex/en/raspberry-pi5-version/assets/image40.BuRtmXDG.png",wt="/projects/AiNex/en/raspberry-pi5-version/assets/image41.DgsXH2nA.jpeg",At="/projects/AiNex/en/raspberry-pi5-version/assets/image42.D-yi6hmH.png",vt="/projects/AiNex/en/raspberry-pi5-version/assets/image2.cMMNUvrM.png",kt="/projects/AiNex/en/raspberry-pi5-version/assets/image3.BislomiP.png",_t="/projects/AiNex/en/raspberry-pi5-version/assets/image2.B3-Wkm7D.png",Ct="/projects/AiNex/en/raspberry-pi5-version/assets/image3.DlCbrNem.png",jt="/projects/AiNex/en/raspberry-pi5-version/assets/image4.DR2En7LB.png",Nt="/projects/AiNex/en/raspberry-pi5-version/assets/image5.CQVruakR.png",Ot=JSON.parse('{"title":"1. ROS Robot Introductory Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1.ROS Robot Introductory Course.md","filePath":"docs/1.ROS Robot Introductory Course.md"}'),It={name:"docs/1.ROS Robot Introductory Course.md"};function Rt(St,e,qt,Pt,zt,Tt){return s(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_1-ros-robot-introductory-course" tabindex="-1">1. ROS Robot Introductory Course <a class="header-anchor" href="#_1-ros-robot-introductory-course" aria-label="Permalink to &quot;1. ROS Robot Introductory Course&quot;">​</a></h1><h2 id="_1-1-getting-started" tabindex="-1">1.1 Getting Started <a class="header-anchor" href="#_1-1-getting-started" aria-label="Permalink to &quot;1.1 Getting Started&quot;">​</a></h2><h3 id="_1-1-1-introduction-to-ainex" tabindex="-1">1.1.1 Introduction to AiNex <a class="header-anchor" href="#_1-1-1-introduction-to-ainex" aria-label="Permalink to &quot;1.1.1 Introduction to AiNex&quot;">​</a></h3><p>AiNex Intelligent Vision Humanoid Robot is a competition robot developed based on the Raspberry Pi 5. The entire body has 24 degrees of freedom, featuring axially moving hip joints, high performance, and great flexibility. It can perform complex actions such as walking straight, turning in place, going up and down stairs, hurdling, and more.</p><p>The head of the AiNex robot is equipped with a high-definition wide-angle camera module with 2 degrees of freedom, capable of functions like color recognition and face tracking. Additionally, the head is fitted with a camera protection bracket.</p><p>The mainboard runs on the Ubuntu 20.04 system and is equipped with the Robot Operating System (ROS) Noetic.</p><p>The robot utilizes OpenCV for image recognition and employs PID algorithms for quick object position capture, enabling it to autonomously perform tasks such as kicking ball, visual line following, and autonomous handling.</p><h4 id="packing-list" tabindex="-1">Packing List <a class="header-anchor" href="#packing-list" aria-label="Permalink to &quot;Packing List&quot;">​</a></h4><img loading="lazy" height="192" width="762" src="'+c+'" class="common_img" style="width:553px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>Upon receiving AiNex, please refer to the packing list to check if all the accessories are included. If any parts are missing, please contact our support team at <a href="mailto:support@hiwonder.com" target="_blank" rel="noreferrer">support@hiwonder.com</a>.</p></div><h3 id="_1-1-2-preparation" tabindex="-1">1.1.2 Preparation <a class="header-anchor" href="#_1-1-2-preparation" aria-label="Permalink to &quot;1.1.2 Preparation&quot;">​</a></h3><h4 id="_1-1-2-1-charging-instruction" tabindex="-1">1.1.2.1 Charging Instruction <a class="header-anchor" href="#_1-1-2-1-charging-instruction" aria-label="Permalink to &quot;1.1.2.1 Charging Instruction&quot;">​</a></h4><p>AiNex robot is powered by an 11.1V lithium battery. Please use the dedicated charger provided with the kit. Due to the need to power off the robot during transportation and limitations on fully charging the battery, users are required to charge the battery using the provided dedicated charger before the initial startup.</p><p>It typically takes around 1 hours to reach a full charge. Additionally, to maintain the optimal performance of the robot, please charge the battery promptly when the voltage is ≤10V.</p><p>The operations for charging are as follow:</p><ol><li><p>Turn <strong>OFF</strong> the robot. <img loading="lazy" height="893" width="1267" src="'+d+'" class="common_img" style="width:800px;"></p></li><li><p>Connect battery wires, ensuring that each wire matches its corresponding color. <img loading="lazy" height="458" width="635" src="'+p+'" class="common_img" style="width:277px;"><img loading="lazy" height="449" width="622" src="'+h+'" class="common_img" style="width:271px;"></p></li><li><p>Connect the provided charger to the DC power port of the Raspberry Pi expansion board as pictured:</p></li></ol><p><img loading="lazy" height="429" width="607" src="'+g+'" class="common_img" style="width:300px;"><img loading="lazy" height="439" width="608" src="'+m+'" class="common_img" style="width:300px;"></p><ol start="4"><li>If the indicator is in red, it means that the battery is being charged. When the indicator turns green, the battery is fully charged. The charging time is about 3 hours.</li></ol><h4 id="_1-1-2-1-precaution-for-the-use-of-lipo-battery" tabindex="-1">1.1.2.1 Precaution for the Use of LiPo Battery <a class="header-anchor" href="#_1-1-2-1-precaution-for-the-use-of-lipo-battery" aria-label="Permalink to &quot;1.1.2.1 Precaution for the Use of LiPo Battery&quot;">​</a></h4><p>Due to the need to power off the robot during transportation and limitations on fully charging the battery, users are required to charge the battery using the provided dedicated charger before the initial startup.</p><ol><li><p>Please refrain from connecting the battery wires until they are properly connected to the Raspberry Pi expansion board. Otherwise, there is a risk of a short circuit occurring due to contact between the positive and negative terminals.</p></li><li><p>Charge the robot with the special charger.</p></li><li><p>The indicator is in green when the charger is not connected to the battery.</p></li><li><p>If robot won&#39;t be used in a long period of time, please fully charge battery first, then disconnect battery wires.</p></li><li><p>Always keep battery in cool and dry environment, otherwise battery lifespan gets shortened. Never intentionally hit, throw or step on Lipo battery.</p></li><li><p>Do not hit, throw or step on the battery.</p></li><li><p>Do not use battery in areas with strong static electricity or magnetic fields, as this lead to damage to battery.</p></li><li><p>Do not insert battery into socket and connect battery terminals with metal objects.</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Solemn Declaration: Our company shall not bear any responsibility for any product damage, economic losses, safety accidents, or other consequences caused by failure to follow the above &quot;Precaution for the Use of LiPo Battery” .</strong></p></div><h2 id="_1-2-first-start" tabindex="-1">1.2 First Start <a class="header-anchor" href="#_1-2-first-start" aria-label="Permalink to &quot;1.2 First Start&quot;">​</a></h2><h3 id="_1-2-1-robot-hardware-structure" tabindex="-1">1.2.1 Robot Hardware Structure <a class="header-anchor" href="#_1-2-1-robot-hardware-structure" aria-label="Permalink to &quot;1.2.1 Robot Hardware Structure&quot;">​</a></h3><h4 id="_1-2-1-1-introduction-to-hardware" tabindex="-1">1.2.1.1 Introduction to Hardware <a class="header-anchor" href="#_1-2-1-1-introduction-to-hardware" aria-label="Permalink to &quot;1.2.1.1 Introduction to Hardware&quot;">​</a></h4><p>This section mainly introduces the robot&#39;s hardware, including the main control system, bus servos, high-definition camera, and voltage display module.</p><img loading="lazy" height="663" width="888" src="'+u+'" class="common_img" style="width:553px;"><h4 id="_1-2-1-2-introduction-to-main-controller" tabindex="-1">1.2.1.2 Introduction to Main Controller <a class="header-anchor" href="#_1-2-1-2-introduction-to-main-controller" aria-label="Permalink to &quot;1.2.1.2 Introduction to Main Controller&quot;">​</a></h4><p>The Raspberry Pi 5 uses a 64-bit quad-core Arm Cortex-A76 processor with a clock frequency of 2.4GHz. It provides 2 to 3 times the CPU performance compared to the Raspberry Pi 4. In addition to a significantly improved 800MHz VideoCore VII GPU for graphics performance, it supports dual 4Kp60 display output via HDMI, as well as advanced camera support with a redesigned Raspberry Pi image signal processor. This can provide smooth desktop experience and open up new applications for you.</p><p>This is the first full-size Raspberry Pi computer using chips built internally by Raspberry Pi. RP1 provides most of the I/O functions for the Raspberry Pi 5 and achieves a leap in peripheral performance and functionality. The total USB bandwidth has increased by more than twice, accelerating the transfer speed to external UAS drives and other high-speed peripherals. The dedicated dual-channel 1Gbps MIPI camera and display interfaces on early models have been replaced by a pair of four-channel 1.5Gbps MIPI transceivers, increasing the total bandwidth by three times and supporting any combination of up to two cameras or displays. The peak SD card performance is doubled by supporting SDR104 high-speed mode. For the first time, this platform introduces a single-channel PCIExpress 2.0 interface, providing support for high-bandwidth peripherals.</p><p>For more information about the Raspberry Pi mainboard, please refer to &quot;<strong>4. Raspberry Pi Baord and Expansion Board</strong>”.</p><img loading="lazy" height="592" width="934" src="'+y+'" class="common_img" style="width:445px;"><h4 id="_1-2-1-3-hd-camera" tabindex="-1">1.2.1.3 HD Camera <a class="header-anchor" href="#_1-2-1-3-hd-camera" aria-label="Permalink to &quot;1.2.1.3 HD Camera&quot;">​</a></h4><p>In daily life, cameras are generally used to perform basic functions such as taking photos and recording videos.</p><p>With the advent of artificial intelligence, there is a growing demand for obtaining more intelligent results from cameras. That is, by analyzing the changes in the environment through the camera&#39;s field of view, making judgments, and feeding the results back to the terminal or cloud processors, to serve richer applications.</p><p>Its advantages lie in its simple sensors, low cost, ease of calibration, and recognition. Its disadvantage is that it cannot determine the real size of an object. It may be a large object far away or a small object nearby.</p><img loading="lazy" height="637" width="902" src="'+b+'" class="common_img" style="width:394px;"><p>The specific parameters of the camera used in AiNex can be referred to in the following table:</p><table><colgroup><col style="width:27%;"><col style="width:72%;"></colgroup><tbody><tr><td style="text-align:center;">Parameter</td><td style="text-align:center;">Description</td></tr><tr><td style="text-align:center;">FOV</td><td style="text-align:center;">170°</td></tr><tr><td style="text-align:center;">Focal length</td><td style="text-align:center;">3.2mm</td></tr><tr><td style="text-align:center;"><p>Dimension</p><p>（Unit：mm）</p></td><td style="text-align:center;">30*25*25.0 ±0.5mm</td></tr><tr><td style="text-align:center;">Storage temperature</td><td style="text-align:center;">-30℃~70℃</td></tr><tr><td style="text-align:center;">Operating temperature</td><td style="text-align:center;">0℃~50℃</td></tr><tr><td style="text-align:center;">Focus</td><td style="text-align:center;">Fixed</td></tr><tr><td style="text-align:center;">Focus</td><td style="text-align:center;">Manual lens focusing by twisting</td></tr><tr><td style="text-align:center;">Object Distance</td><td style="text-align:center;">30cm to infinity</td></tr><tr><td style="text-align:center;">Center Sharpness</td><td style="text-align:center;">600LW/PH（CENTER）</td></tr><tr><td style="text-align:center;">Data Transmission</td><td style="text-align:center;">USB2.0</td></tr><tr><td style="text-align:center;">Power Supply</td><td style="text-align:center;">USB bus end</td></tr><tr><td style="text-align:center;">Power Supply Voltage</td><td style="text-align:center;">DC 5V±5%</td></tr><tr><td style="text-align:center;">Maximum Power Consumption</td><td style="text-align:center;">40mW</td></tr><tr><td style="text-align:center;">System</td><td style="text-align:center;">Support Win XP/win 7、8 / vista /android 4.0/ mac /Linux with uvc</td></tr><tr><td style="text-align:center;">Maximum Effective Pixels</td><td style="text-align:center;">640（H）*480（V）</td></tr><tr><td style="text-align:center;">Sensitivity</td><td style="text-align:center;">2.5v / (lux-sec)</td></tr><tr><td style="text-align:center;">Pixel Size</td><td style="text-align:center;">3.4µm x 3.4µm</td></tr><tr><td style="text-align:center;">Resolutions and Frame Rates</td><td style="text-align:center;"><p>YUY2 160x120 30FPS</p><p>YUY2 176x144 30FPS</p><p>YUY2 320x240 30FPS</p><p>YUY2 352x288 30FPS</p><p>YUY2 640x480 30FPS</p></td></tr><tr><td style="text-align:center;">Signal-to-Noise Ratio</td><td style="text-align:center;">42db</td></tr><tr><td style="text-align:center;">Dynamic Range</td><td style="text-align:center;">58db</td></tr><tr><td style="text-align:center;">Shutter Type</td><td style="text-align:center;">Electronic rolling shutter</td></tr><tr><td style="text-align:center;">Automatic Exposure Control (AEC)</td><td rowspan="3" style="text-align:center;">Support</td></tr><tr><td style="text-align:center;">Automatic White Balance (AEB)</td></tr><tr><td style="text-align:center;">Automatic Gain Control (AGC)</td></tr><tr><td style="text-align:center;">Output Image Format</td><td style="text-align:center;">YUY2/MJPEG</td></tr><tr><td style="text-align:center;">Lens Structure</td><td style="text-align:center;">4E+IR</td></tr><tr><td style="text-align:center;">Aperture</td><td style="text-align:center;">2.4</td></tr><tr><td style="text-align:center;">Distortion</td><td style="text-align:center;">＜7.6%</td></tr></tbody></table><h4 id="_1-2-1-4-hv-bus-servo" tabindex="-1">1.2.1.4 HV Bus Servo <a class="header-anchor" href="#_1-2-1-4-hv-bus-servo" aria-label="Permalink to &quot;1.2.1.4 HV Bus Servo&quot;">​</a></h4><p>AiNex&#39;s body consists of 3 types of bus servos, totaling 24 in number, namely HX-12H, HX-35H, and HX-35HM.</p><p>Bus servos utilize serial communication, connecting multiple servos to the control system via a single bus. Compared to digital servos, bus servos can be daisy-chained through a single I/O port, providing strong load capacity, high stability, and ease of maintenance and use. For more details, you can refer to “ <strong>Appendix/ 7. Servo Data</strong>”.</p><p>Regarding the pinout and explanation of the interface pins, taking the HX-35H servo as an example, it is illustrated in the following diagram:</p><img loading="lazy" height="441" width="966" src="'+x+'" class="common_img" style="width:554px;"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Pin</strong></th><th style="text-align:center;"><strong>Instruction</strong></th></tr></thead><tbody><tr><td style="text-align:center;">-</td><td style="text-align:center;">Power ground</td></tr><tr><td style="text-align:center;">+</td><td style="text-align:center;">Power input</td></tr><tr><td style="text-align:center;">S</td><td style="text-align:center;">Signal terminal (half-duplex UART asynchronous serial interface)</td></tr></tbody></table><h4 id="_1-1-2-5-digital-display-module" tabindex="-1">1.1.2.5 Digital Display Module <a class="header-anchor" href="#_1-1-2-5-digital-display-module" aria-label="Permalink to &quot;1.1.2.5 Digital Display Module&quot;">​</a></h4><p>The digital display voltage module is an electronic device used for measuring and displaying voltage. It typically consists of a voltage sensor and a digital display. The voltage sensor converts the input voltage into a digital signal, which is then transmitted to the digital display by control circuitry to show the voltage value. This module is suitable for various occasions where voltage measurement and display are needed, such as laboratories, industrial control, etc.</p><img loading="lazy" height="295" width="295" src="'+f+'" class="common_img" style="width:129px;"><h3 id="_1-2-2-first-start-examination" tabindex="-1">1.2.2 First Start &amp; Examination <a class="header-anchor" href="#_1-2-2-first-start-examination" aria-label="Permalink to &quot;1.2.2 First Start &amp; Examination&quot;">​</a></h3><h4 id="_1-2-2-1-notes" tabindex="-1">1.2.2.1 Notes: <a class="header-anchor" href="#_1-2-2-1-notes" aria-label="Permalink to &quot;1.2.2.1 Notes:&quot;">​</a></h4><ol><li><p>To enable the robot to operate steadily, please fully charge the robot when the battery voltage drops below 10V. For instructions on charging the robot, please refer to “1. ROS Robot Introductory Course/1. Getting Started/Lesson 2 Preparation”.</p></li><li><p>Keep your face and eyes away from the robot during the robot is moving.</p></li><li><p>Never put your finger near the robot&#39;s joints to prevent any risk of pinching.</p></li><li><p>Keep an eye on edge to protect robot from falling.</p></li><li><p>Continuous operation can cause servos to heat up. Please allow servos to cool down through a period of rest before resuming operation.</p></li><li><p>Get servo changed after prolonged or excessive use.</p></li></ol><h4 id="_1-2-2-2-start-the-robot" tabindex="-1">1.2.2.2 Start the Robot <a class="header-anchor" href="#_1-2-2-2-start-the-robot" aria-label="Permalink to &quot;1.2.2.2 Start the Robot&quot;">​</a></h4><ol><li>Prior to initiating the robot, ensure that the battery cable and USB cable are firmly connected.</li></ol><img loading="lazy" height="596" width="864" src="'+w+'" class="common_img" style="width:335px;"><ol start="2"><li><p>To prevent servo damage caused by sudden force, please refrain from folding the robot&#39;s legs, and ensure that the robot is positioned as shown in the picture. <img loading="lazy" height="946" width="866" src="'+A+'" class="common_img" style="width:800px;"></p></li><li><p>Turn on the expansion board. After waiting for around 1 second, you will hear the “Di” sound from buzzer, and then the robot stands up. When MODE indicator turns green, it indicates that the robot is boot up successfully.</p></li></ol><img loading="lazy" height="835" width="866" src="'+v+'" class="common_img" style="width:346px;"><img loading="lazy" height="785" width="1088" src="'+k+'" class="common_img" style="width:475px;"><img loading="lazy" height="811" width="1124" src="'+_+'" class="common_img" style="width:490px;"><ol start="4"><li>The robot will enter the default AP direct connection mode, and generate a WiFi starting with “<strong>HW</strong>” after it boots up successfully, and the password is “<strong>hiwonder</strong>”. <img loading="lazy" height="55" width="349" src="'+C+'" class="common_img" style="width:349px;"></li></ol><h3 id="_1-2-3-app-installation-connection" tabindex="-1">1.2.3 App Installation &amp; Connection <a class="header-anchor" href="#_1-2-3-app-installation-connection" aria-label="Permalink to &quot;1.2.3 App Installation &amp; Connection&quot;">​</a></h3><h4 id="_1-2-3-1-preparation" tabindex="-1">1.2.3.1 Preparation <a class="header-anchor" href="#_1-2-3-1-preparation" aria-label="Permalink to &quot;1.2.3.1 Preparation&quot;">​</a></h4><ul><li><strong>App Installation</strong></li></ul><ol><li><p><strong>Android:</strong> transfer the app installation pack stored in “<strong>app</strong> <strong>installation package</strong>” folder. Please ensure all the permissions are allowed for this app, otherwise the app functions will be affected!</p></li><li><p><strong>iOS:</strong> download “<strong>WonderROS</strong>” app from App Store.</p></li></ol><p>Please enable location service and WiFi before using the app.</p><ul><li><strong>Start the Robot</strong></li></ul><p>Start the robot according to the robot according to the instructions provided in “<strong>1. ROS Robot Introductory/ 2. First Start/ 2. First Start &amp; Examination”.</strong></p><h4 id="_1-2-3-2-device-connection" tabindex="-1">1.2.3.2 Device Connection <a class="header-anchor" href="#_1-2-3-2-device-connection" aria-label="Permalink to &quot;1.2.3.2 Device Connection&quot;">​</a></h4><p>After a successful boot-up, the robot will enter AP direct connection mode and create a WiFi network with the name starting with &#39;<strong>HW</strong>.&#39; Simply connect your phone to this &#39;<strong>HW</strong>&#39; WiFi network to begin playing the games.</p><p>Two network modes are available: direct connection mode and LAN mode.</p><ul><li><strong>Introduction to Connection Mode</strong></li></ul><p>There are two network modes, including AP direct connection mode and STA LAN mode.</p><ol><li><p>AP direct connection mode: the controller generates a WiFi which can be connected by phones. This WiFi has no internet access.</p></li><li><p>STA LAN mode: the controller actively connects to specific WiFi. You can access Internet in this mode.</p></li></ol><p>Enabling LAN mode or direct connection mode may not be successful. AiNex will default to AP direct connection mode. Whether you select AP direct connection mode or STA LAN mode, the robot will function in the same manner.</p><p>However, it is recommended to experience robot games under <strong>Direct Connection Mode</strong> first.</p><ul><li><strong>Direct Connection (Must Read)</strong></li></ul><p>Take the instructions on Android app as example. The instructions are also applicable to iOS app.</p><p>Prior to operations, please turn on the robot.</p><ol><li>Open “<strong>WonderROS</strong>” app, then tap-on “<strong>AiNex</strong>”.</li></ol><img loading="lazy" height="540" width="1200" src="'+o+'" class="common_img" style="width:553px;"><ol start="2"><li>Click “<strong>+</strong>” button, and select “<strong>Direct Connection Mode</strong>”.</li></ol><p><img loading="lazy" height="623" width="1267" src="'+j+'" class="common_img" style="width:800px;"><img loading="lazy" height="857" width="1731" src="'+i+'" class="common_img" style="width:800px;"></p><img loading="lazy" height="317" width="420" src="'+N+'" class="common_img" style="width:280px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>for iOS user, please do not return back to the app until the WiFi icon <img loading="lazy" height="52" width="52" src="'+I+'" class="inline-icon"> appears above, otherwise the robot cannot be searched. If the robot cannot be searched, please click <img loading="lazy" height="45" width="46" src="'+R+'" class="inline-icon"> to refresh.</strong></p></div><ol start="3"><li>After successfully connecting to the robot WiFi, app automatically connects to the robot. When the robot icon appears, it means the connection is successful.</li></ol><img loading="lazy" height="540" width="1200" src="'+n+'" class="common_img" style="width:553px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If you are informed of “No Internet Connection. Whether to keep connection”, just select “Keep Connection”.</strong></p></div><ul><li><strong>LAN Mode (Optional)</strong></li></ul><p>Take the instructions on Android app as example. The instructions are also applicable to iOS app.</p><ol><li><p>Join the local WiFi. Take “<strong>hiwonder_5G</strong>” as example. <img loading="lazy" height="285" width="1028" src="'+S+'" class="common_img" style="width:800px;"></p></li><li><p>Open “<strong>Wonder ROS</strong>” app and select “<strong>AiNex</strong>”. <img loading="lazy" height="540" width="1200" src="'+o+'" class="common_img" style="width:800px;"></p></li><li><p>After successful network connection, return to the app. Then tap-on “<strong>+</strong>” button at lower right corner and select “<strong>LAN mode</strong>”. <img loading="lazy" height="623" width="1267" src="'+q+'" class="common_img" style="width:800px;"></p></li><li><p>Enter the Wi-Fi password. Having entered the password, click-on “<strong>OK</strong>” button. Please ensure the password you enter is correct. <img loading="lazy" height="623" width="1267" src="'+P+'" class="common_img" style="width:800px;"></p></li><li><p>Click “<strong>Go to connect device hotspots</strong>”. Join the WiFi starting with HW, and input the password “<strong>hiwonder</strong>”. After connection, return to the app interface. <img loading="lazy" height="857" width="1731" src="'+i+'" class="common_img" style="width:800px;"></p></li><li><p>Then, WonderROS app is connecting to the robot automatically. <img loading="lazy" height="640" width="1269" src="'+z+'" class="common_img" style="width:800px;"></p></li><li><p>After a while, the robotic icon will show up. <img loading="lazy" height="540" width="1200" src="'+n+'" class="common_img" style="width:800px;"></p></li><li><p>Press AiNex robotic icon to check the IP and ID assigned to the robot. <img loading="lazy" height="622" width="1266" src="'+T+'" class="common_img" style="width:800px;"></p></li><li><p>If you need to revert to AP direct connection mode, press the robot icon again and click-on “<strong>Set as direct connection mode</strong>” until the LED light flashes. <img loading="lazy" height="622" width="1266" src="'+E+'" class="common_img" style="width:800px;"></p></li></ol><h3 id="_1-2-4-app-control" tabindex="-1">1.2.4 App Control <a class="header-anchor" href="#_1-2-4-app-control" aria-label="Permalink to &quot;1.2.4 App Control&quot;">​</a></h3><h4 id="_1-2-4-1-preparation" tabindex="-1">1.2.4.1 Preparation <a class="header-anchor" href="#_1-2-4-1-preparation" aria-label="Permalink to &quot;1.2.4.1 Preparation&quot;">​</a></h4><p>Install WonderROS app and connect the robot to the app according to the tutorial saved in “<strong>1. ROS Robot Introductory Course/ 2. First Start/ 3. APP &amp; Handle Control/ 3. App Installation &amp; Connection</strong>.</p><h4 id="_1-2-4-2-start-the-game" tabindex="-1">1.2.4.2 Start the Game <a class="header-anchor" href="#_1-2-4-2-start-the-game" aria-label="Permalink to &quot;1.2.4.2 Start the Game&quot;">​</a></h4><p>Click-on AiNex robotic icon to enter the mode selection interface.</p><img loading="lazy" height="611" width="1268" src="'+O+'" class="common_img" style="width:800px;"><ul><li><strong>Robot Control</strong></li></ul><ol><li>Click the &quot;<strong>robot control</strong>&quot; icon to enter the game interface. Upon entering the game interface, AiNex will reset to its initial posture. <img loading="lazy" height="611" width="1268" src="'+F+'" class="common_img" style="width:800px;"></li></ol><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="122" width="134" src="'+D+'" class="inline-icon"></td><td style="text-align:center;">Drag the joystick to control the robot to go forward or backward, and move left and right.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="172" width="384" src="'+V+'" class="common_img" style="width:241px;"></td><td style="text-align:center;">“<strong>Action</strong>&quot; button enables the robot to execute predefined action groups, while the &quot;<strong>Attention</strong>&quot; button is used to guide the robot back to its initial posture. Additionally, the &quot;<strong>Get up</strong>&quot; button is employed to command the robot to recover from a fall and stand up</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="116" width="199" src="'+B+'" class="common_img" style="width:199px;"></td><td style="text-align:center;">Live camera feed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="115" width="436" src="'+W+'" class="common_img" style="width:215px;"></td><td style="text-align:center;">Adjust robot’s speed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="220" width="197" src="'+M+'" class="common_img" style="width:136px;"></td><td style="text-align:center;">Control robot’s head movements</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="420" width="145" src="'+U+'" class="inline-icon"></td><td style="text-align:center;">Adjust robot’s body height</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="56" width="104" src="'+H+'" class="inline-icon"></td><td style="text-align:center;">Control the robot turn left and right</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="64" width="93" src="'+L+'" class="inline-icon"></td><td style="text-align:center;">Double click the screen to reset the robot’s head back to the middle.</td></tr></tbody></table><ol start="2"><li>If you want to go back to the mode selection interface, click-on <img loading="lazy" height="48" width="48" src="'+t+'" class="inline-icon">.</li></ol><ul><li><strong>Auto Shooting</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ol><li><p><strong>Please operate in the well-lit indoor and avoid direct exposure to intense sunlight.</strong></p></li><li><p><strong>To prevent misrecognition, kindly remove objects that are the same color as the target.</strong></p></li><li><p><strong>If the recognition performance falls below the standard, you should adjust the color threshold based on the file saved in &quot;6. AI Vision Lesson/ 2. ROS+OpenCV Vision Recognition &amp; Tracking\\ Lesson 2 Color Threshold Adjustment&quot;.</strong></p></li></ol></div><p>Click “<strong>Auto Shooting</strong>” to enter the game interface. Its interface consists of two parts:</p><p>（1）The left side is game control area</p><p>（2）The right side is live camera feed</p><img loading="lazy" height="611" width="1266" src="'+Z+'" class="common_img" style="width:553px;"><ol><li>Icon function</li></ol><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon function</strong></th><th style="text-align:center;"><strong>Icon function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="77" width="240" src="'+X+'" class="common_img" style="width:148px;"></td><td style="text-align:center;">Start/ stop the game</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="107" width="444" src="'+J+'" class="common_img" style="width:167px;"><img loading="lazy" height="102" width="425" src="'+G+'" class="common_img" style="width:186px;"></td><td style="text-align:center;">Adjust color threshold range from 0.05 to 1.00</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="90" width="203" src="'+K+'" class="common_img" style="width:131px;"></td><td style="text-align:center;">Extract the color of the designated area on the live camera feed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="158" width="202" src="'+Y+'" class="inline-icon"></td><td style="text-align:center;">Display the extracted color</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="671" width="982" src="'+Q+'" class="common_img" style="width:183px;"></td><td style="text-align:center;">Display the live camera feed</td></tr></tbody></table><ol start="2"><li>Instructions:</li></ol><p>（1）Click-on “<strong>Pick</strong>” button, then drag the red circle onto the target object to pick the color. <img loading="lazy" height="611" width="1266" src="'+$+'" class="common_img" style="width:553px;"></p><p>（2）Tap-on “<strong>OK</strong>” button, then the selected color will be displayed in the box. <img loading="lazy" height="614" width="1269" src="'+tt+'" class="common_img" style="width:554px;"></p><p>（3）After the game starts, the robot will determine the location of the target for shooting. <img loading="lazy" height="609" width="1264" src="'+et+'" class="common_img" style="width:552px;"></p><p>（4）If you want to go back to the mode selection interface, tap-on the blank area to make the navigation bar pop up. Then tap-on <img loading="lazy" height="48" width="48" src="'+t+'" class="inline-icon">.</p><ul><li><strong>Vision Line Following</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ol><li><p><strong>Please operate in the well-lit indoor and avoid direct exposure to intense sunlight.</strong></p></li><li><p><strong>To prevent misrecognition, kindly remove objects that are the same color as the target.</strong></p></li><li><p><strong>If the recognition performance falls below the standard, you should adjust the color threshold based on the file saved in &quot;6. AI Vision Lesson/ 2. ROS+OpenCV Vision Recognition &amp; Tracking/ Lesson 2 Color Threshold Adjustment&quot;.</strong></p></li></ol></div><p>Click “<strong>Vision Line Following</strong>” to enter the game interface. Its interface consists of two parts:</p><p>（1）The left side is game control area</p><p>（2）The right side is live camera feed</p><img loading="lazy" height="611" width="1268" src="'+ot+'" class="common_img" style="width:553px;"><ol><li>Icon function</li></ol><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="61" width="220" src="'+it+'" class="common_img" style="width:146px;"></td><td style="text-align:center;">Start/ stop the game</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="103" width="446" src="'+nt+'" class="common_img" style="width:160px;"></td><td style="text-align:center;">Adjust color threshold range from 0.05 to 1.00</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="91" width="203" src="'+rt+'" class="common_img" style="width:125px;"></td><td style="text-align:center;">Extract the color of the designated area on the live camera feed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="157" width="204" src="'+st+'" class="inline-icon"></td><td style="text-align:center;">Display the extracted color</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="265" width="383" src="'+at+'" class="common_img" style="width:199px;"></td><td style="text-align:center;">Display the live camera feed</td></tr></tbody></table><ol start="2"><li>Instructions</li></ol><p>（1）Tap-on “<strong>Pick</strong>” color, then drag the red circle onto the target object to pick the color. <img loading="lazy" height="611" width="1266" src="'+lt+'" class="common_img" style="width:800px;"></p><p>（2）Tap-on “<strong>OK</strong>” button, then the selected color will be displayed in the box. <img loading="lazy" height="611" width="1267" src="'+ct+'" class="common_img" style="width:800px;"></p><p>（3）After the game starts, the robot will ascertain the location of the target for line following. <img loading="lazy" height="611" width="1268" src="'+dt+'" class="common_img" style="width:800px;"></p><p>（4）If you want to go back to the mode selection interface, tap-on the blank area to make the navigation bar pop up. Then tap-on <img loading="lazy" height="48" width="48" src="'+t+'" class="inline-icon">.</p><ul><li><strong>Target Tracking</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ol><li><p><strong>Please operate in the well-lit indoor and avoid direct exposure to intense sunlight.</strong></p></li><li><p><strong>To prevent misrecognition, kindly remove objects that are the same color as the target.</strong></p></li><li><p><strong>If the recognition performance falls below the standard, you should adjust the color threshold based on the file saved in &quot;6. AI Vision Lesson\\ 2. ROS+OpenCV Vision Recognition &amp; Tracking\\ Lesson 2 Color Threshold Adjustment&quot;.</strong></p></li></ol></div><p>Click “<strong>Target Tracking</strong>” to enter the game interface. Its interface consists of two parts:</p><p>（1）The left side is game control area</p><p>（2）The right side is live camera feed</p><img loading="lazy" height="611" width="1265" src="'+pt+'" class="common_img" style="width:800px;"><ol><li>Function</li></ol><table tabindex="0"><thead><tr><th style="text-align:center;"></th><th style="text-align:center;"></th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Icon</strong></td><td style="text-align:center;"><strong>Function</strong></td></tr><tr><td style="text-align:center;"><img loading="lazy" height="57" width="218" src="'+ht+'" class="common_img" style="width:147px;"></td><td style="text-align:center;">Start/ stop the game</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="104" width="433" src="'+gt+'" class="common_img" style="width:148px;"></td><td style="text-align:center;">Adjust color threshold range from 0.05 to 1.00</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="91" width="202" src="'+mt+'" class="common_img" style="width:127px;"></td><td style="text-align:center;">Extract the color of the designated area on the live camera feed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="160" width="204" src="'+ut+'" class="inline-icon"></td><td style="text-align:center;">Display the extracted color</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="675" width="984" src="'+yt+'" class="common_img" style="width:156px;"></td><td style="text-align:center;">Display the live camera feed</td></tr></tbody></table><ol start="2"><li>Instructions:</li></ol><p>（1）Tap-on “<strong>Pick</strong>” color, then drag the red circle onto the target object to pick the color. <img loading="lazy" height="611" width="1267" src="'+bt+'" class="common_img" style="width:800px;"></p><p>（2）Tap-on “<strong>OK</strong>” button, then the selected color will be displayed in the box. <img loading="lazy" height="471" width="969" src="'+xt+'" class="common_img" style="width:800px;"></p><p>（3）After the game starts, the robot will ascertain the location of the target for movement tracking. <img loading="lazy" height="466" width="966" src="'+ft+'" class="common_img" style="width:800px;"></p><p>（4）If you want to go back to the mode selection interface, tap-on the blank area to make the navigation bar pop up. Then tap-on <img loading="lazy" height="48" width="48" src="'+t+'" class="inline-icon">.</p><ul><li><strong>Face Detection</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>the robot is capable of recognizing faces even when individuals are wearing masks and can simultaneously recognize multiple faces.</p></div><p>Click “<strong>Face Detection</strong>” to enter the game interface. Its interface consists of two parts:</p><p>（1）The left side is game control area</p><p>（2）The right side is live camera feed</p><img loading="lazy" height="611" width="1268" src="'+wt+'" class="common_img" style="width:800px;"><ol><li>Tap-on “<strong>Start</strong>” button. The robot can detect human face within 1 meter. Once detecting human face, the robot will execute “<strong>waving</strong>” action.</li></ol><table tabindex="0"><thead><tr><th style="text-align:center;"></th><th style="text-align:center;"></th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Icon</strong></td><td style="text-align:center;"><strong>Function</strong></td></tr><tr><td style="text-align:center;"><img loading="lazy" height="71" width="257" src="'+At+'" class="common_img" style="width:130px;"></td><td style="text-align:center;">Start/ stop the game</td></tr></tbody></table><ol start="2"><li>If you want to go back to the mode selection interface, tap-on the blank area to make the navigation bar pop up. Then tap-on <img loading="lazy" height="48" width="48" src="'+t+'" class="inline-icon">.</li></ol><h3 id="_1-2-5-wireless-handle-control" tabindex="-1">1.2.5 Wireless Handle Control <a class="header-anchor" href="#_1-2-5-wireless-handle-control" aria-label="Permalink to &quot;1.2.5 Wireless Handle Control&quot;">​</a></h3><h4 id="_1-2-5-1-notes" tabindex="-1">1.2.5.1 Notes <a class="header-anchor" href="#_1-2-5-1-notes" aria-label="Permalink to &quot;1.2.5.1 Notes&quot;">​</a></h4><ol><li><p>Check whether the handle receiver has been properly inserted into the handle. Typically, the handle receiver is inserted before delivery.</p></li><li><p>Insert two AAA batteries ensuring the connection of the positive and negative terminals is correct.</p></li></ol><img loading="lazy" height="482" width="1288" src="'+vt+'" class="common_img" style="width:582px;"><ol start="3"><li><p>Whenever the robot is turned on, app auto-start service will be enabled. If the app auto-start service is not disabled, you can directly control the robot using wireless handle.</p></li><li><p>To prevent the wireless handle from connecting to the wrong robot, please ensure there are no other robots in the vicinity during operation.</p></li><li><p>If the handle doesn’t connect to the robot within 30s or there is no operation on the handle within 5 minutes after turning on, it will enter sleep mode. And you can press “<strong>START</strong>” to activate the handle.</p></li></ol><h4 id="_1-2-5-2-device-connection" tabindex="-1">1.2.5.2 Device Connection <a class="header-anchor" href="#_1-2-5-2-device-connection" aria-label="Permalink to &quot;1.2.5.2 Device Connection&quot;">​</a></h4><ol><li><p>Turn ON the wireless handle. Then, two LED lights (red and green) will flash simultaneously.</p></li><li><p>After a few seconds, the robot will pair with the wireless handle automatically. When the handle pairs with the handle successfully, green LED light will keep lighting up, while red LED light will go off.</p></li></ol><img loading="lazy" height="309" width="767" src="'+kt+'" class="common_img" style="width:536px;"><h4 id="_1-2-5-3-instructions" tabindex="-1">1.2.5.3 Instructions <a class="header-anchor" href="#_1-2-5-3-instructions" aria-label="Permalink to &quot;1.2.5.3 Instructions&quot;">​</a></h4><p>The functions of the buttons are listed below.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Button</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td style="text-align:center;">Restore initial posture</td></tr><tr><td style="text-align:center;">Move left joystick upward</td><td style="text-align:center;">Go forward</td></tr><tr><td style="text-align:center;">Move left joystick downward</td><td style="text-align:center;">Go backward</td></tr><tr><td style="text-align:center;">Move left joystick left</td><td style="text-align:center;">Move left</td></tr><tr><td style="text-align:center;">Move left joystick right</td><td style="text-align:center;">Move right</td></tr><tr><td style="text-align:center;">Move right joystick upward</td><td style="text-align:center;">Raise body height</td></tr><tr><td style="text-align:center;">Move right joystick downward</td><td style="text-align:center;">Lower body height</td></tr><tr><td style="text-align:center;">Move right joystick left</td><td style="text-align:center;">Rotate counterclockwise</td></tr><tr><td style="text-align:center;">Move right joystick right</td><td style="text-align:center;">Rotate counterclockwise</td></tr></tbody></table><h3 id="_1-2-6-shooting-line-following-quick-start" tabindex="-1">1.2.6 Shooting &amp; Line Following Quick Start <a class="header-anchor" href="#_1-2-6-shooting-line-following-quick-start" aria-label="Permalink to &quot;1.2.6 Shooting &amp; Line Following Quick Start&quot;">​</a></h3><p>To enable the robot to execute auto shooting and line following, user just need to press MODE button.</p><h4 id="_1-2-6-1-preparation" tabindex="-1">1.2.6.1 Preparation <a class="header-anchor" href="#_1-2-6-1-preparation" aria-label="Permalink to &quot;1.2.6.1 Preparation&quot;">​</a></h4><ol><li>Ensure the camera cable is connected to USB port.</li></ol><ol start="2"><li>AiNex completes ball shooting and line following through color recognition. The robot defaults to recognize blue ball and black line. If the recognition performance falls below the standard, you need to adjust the color threshold according to the the file saved in “<strong>6. AI Vision Lesson/ 2. ROS+OpenCV Vision Recognition &amp; Tracking/ Lesson 2 Color Threshold Adjustment</strong>”.</li></ol><ol start="3"><li><p>Verify whether the app&#39;s auto-start service is enabled, typically enabled by default.</p><p>If the auto-start service is disabled, you can connect to robot’s remote system desktop and enter the following command to enable the auto-start service for app.</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_app_node.service</span></span></code></pre></div><p>Regarding remote connection, please refer to“5**. ROS Robot Motion Control/ 1. Basic Control Course/ Lesson 1 Set Development Environment/ Install MobaXterm and Connection**”.</p><h4 id="_1-2-6-2-instructions" tabindex="-1">1.2.6.2 Instructions <a class="header-anchor" href="#_1-2-6-2-instructions" aria-label="Permalink to &quot;1.2.6.2 Instructions&quot;">​</a></h4><p>After booting up, you can change robot’s working mode by press “MODE” buttom. AiNex has three modes: <strong>Normal mode, Shooting mode and Line-following mode</strong>.</p><p>Press “MODE” button to switch mode for the robot. After you hear a “Di” sound, the mode is switched successfully. At the same time, RGB light will display in corresponding color, indicating the corresponding mode.</p><p>The specific instructions are listed below:</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Mode</strong></th><th style="text-align:center;"><strong>RGB light</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">Normal mode (default)</td><td style="text-align:center;">Green</td><td style="text-align:center;">App/ wireless handle control</td></tr><tr><td style="text-align:center;">Shooting mode</td><td style="text-align:center;">Blue</td><td style="text-align:center;">Automatically track the purple ball and kick it away.</td></tr><tr><td style="text-align:center;">Line-following mode</td><td style="text-align:center;">Red</td><td style="text-align:center;">Autonomously follow black line</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ol><li><p><strong>APP control and wireless handle control need to be performed in normal mode (the correspond mode color is green).Do not remotely control the robot using a wireless handle when it functions in shooting mode or line- following mode, which will lead to program crashes and affect the subsequent use of the robot.</strong></p></li><li><p><strong>Long pressing the &quot;MODE&quot; button will shut down the Raspberry Pi, and the buzzer will emit a long beep. It is important to note that this method performs a soft shutdown on the Raspberry Pi. Since the expansion board is still powered, the RGB and indicator lights on the expansion board will remain on. To completely power off, push the switch on the expansion board to &quot;OFF&quot;.</strong></p></li></ol></div><ul><li><strong>Normal Mode</strong></li></ul><p>The robot will enter normal mode by default after booting up, indicated by a green illumination of the RGB light. Under normal mode, you can control the robot using app and wireless handle. For detailed instructions, please refer to the tutorials saved in “<strong>App Control</strong>” and “<strong>Wireless Handle Control</strong>”.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>When in auto shooting and line following modes, avoid using the app and wireless handle to control the robot, as doing so may result in damage to the robot.</strong></p></div><ul><li><strong>Auto Shooting Mode</strong></li></ul><p>The RGB light will change to blue when the robot enters auto shooting mode. Subsequently, the robot&#39;s head will rotate left and right to lock onto the blue ball. After identifying the ball, the robot&#39;s head and body will track its movements, approach it, and then execute the shooting action.</p><img loading="lazy" height="879" width="1217" src="'+_t+'" class="common_img" style="width:531px;"><ul><li><strong>Intelligent Line Following</strong></li></ul><p>In line following mode, RGB light turns red. The robot will lower its head to recognize the black line, then go forward following the black line.</p><img loading="lazy" height="2772" width="3840" src="'+Ct+'" class="common_img" style="width:553px;"><h4 id="_1-2-6-3-open-live-camera-feed" tabindex="-1">1.2.6.3 Open Live Camera Feed <a class="header-anchor" href="#_1-2-6-3-open-live-camera-feed" aria-label="Permalink to &quot;1.2.6.3 Open Live Camera Feed&quot;">​</a></h4><p>Open the system browser and enter “<strong>web_video_server</strong>” to access the <strong>web_video_server</strong> backend.</p><ol><li><p>Enter “<strong>192.168.149.1:8080</strong>” on the search bar of the browser. <img loading="lazy" height="499" width="959" src="'+jt+'" class="common_img" style="width:800px;"></p></li><li><p>Click-on “<strong>/color_detection/image_result</strong>” to access to the live camera feed. <img loading="lazy" height="560" width="903" src="'+Nt+'" class="common_img" style="width:800px;"></p><p>It may be due to the camera cable not being connected properly or the auto-start service not being activated. The specific troubleshooting steps are as follows:</p></li></ol><ol><li><p>Replug the camera connection cable, and then follow the above steps to open the live camera feed and check the effect.</p></li><li><p>Restart the robot&#39;s auto-start service. You can do this by connecting to the remote desktop and entering the restart command in the terminal.</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_app_node.service</span></span></code></pre></div><p>Regarding the remote connection lesson, please refer to “<strong>5. ROS Robot Motion Control/ 1. Basic Control Course/ Lesson 1 Set Environment Development/ Install and Connect MobaXterm</strong>”.</p>',187)])])}const Ft=r(It,[["render",Rt]]);export{Ot as __pageData,Ft as default};
